create table if not exists emails (id uuid primary key, message_id text unique, from_address text not null, to_address text, subject text not null, body_text text not null, received_at timestamptz not null, application_id uuid references applications(id), classification text, classification_confidence numeric(3,2), classification_reason text, ingested_at timestamptz not null default now());
create index if not exists emails_application_idx on emails(application_id);
create table if not exists automation_plans (id uuid primary key, application_id uuid not null references applications(id), target_url text not null, status text not null default 'PREPARED' check (status in ('PREPARED','RUNNING','AWAITING_APPROVAL','AWAITING_SUBMIT_APPROVAL','COMPLETED','SUBMITTED','FAILED','BLOCKED_ANTI_BOT','ABANDONED')), plan jsonb not null, result jsonb not null default '[]', submit_approved boolean not null default false, heartbeat_at timestamptz, idempotency_key text not null unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists automation_plans_status_idx on automation_plans(status, updated_at);
create table if not exists automation_steps (id uuid primary key, plan_id uuid not null references automation_plans(id) on delete cascade, step_key text not null, step_index int not null, status text not null check (status in ('PENDING','RUNNING','COMPLETED','FAILED','SKIPPED')), result jsonb not null default '{}', screenshot_ref text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(plan_id, step_key));
create table if not exists applicant_identities (id uuid primary key, profile_id uuid not null references profiles(id), applicant_email citext not null, username text, credential_ref text, provider text not null default 'LOCAL_MOCK', domain text not null, account_status text not null default 'ACTIVE' check (account_status in ('ACTIVE','DISABLED')), external_account_id text, last_used_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(profile_id, domain));
create table if not exists account_sessions (id uuid primary key, application_id uuid not null references applications(id), applicant_identity_id uuid references applicant_identities(id), automation_plan_id uuid references automation_plans(id), state text not null default 'DISCOVER' check (state in ('DISCOVER','ACCOUNT_REQUIRED','SIGNUP','WAITING_FOR_EMAIL','VERIFY_EMAIL','OTP_REQUIRED','LOGIN','PREPARE','FILL','UPLOAD','REVIEW','SUBMIT','COMPLETED','FAILED','HARD_STOP')), expected_domain text not null, hard_stop_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists account_sessions_application_idx on account_sessions(application_id);
create table if not exists verification_extractions (id uuid primary key, source_email_id uuid not null references emails(id), account_session_id uuid not null references account_sessions(id), verification_type text not null, value_ref text not null, confidence numeric(3,2) not null, expires_at timestamptz, consumed_at timestamptz, rejected_reason text, created_at timestamptz not null default now(), unique(source_email_id));
create table if not exists worker_events (id uuid primary key, event_id text not null unique, plan_id uuid references automation_plans(id), application_id uuid references applications(id), job_id uuid references jobs(id), event_type text not null, payload jsonb not null default '{}', received_at timestamptz not null default now(), processed_at timestamptz);
create index if not exists worker_events_plan_idx on worker_events(plan_id, received_at);
create table if not exists autonomy_policies (action_kind text primary key, autonomy_level text not null check (autonomy_level in ('AUTO','REQUIRES_APPROVAL','FORBIDDEN')), reason text not null, updated_at timestamptz not null default now());
alter table applications add column if not exists account_session_id uuid references account_sessions(id);
alter table applications add column if not exists recruiter_thread_key text;
insert into autonomy_policies(action_kind, autonomy_level, reason) select x.action_kind, x.autonomy_level, x.reason from (values ('ACCOUNT_CREATION','REQUIRES_APPROVAL','External account creation requires explicit approval.'),('EMAIL_VERIFICATION','AUTO','Only deterministic, fresh, domain-matched verification may continue.'),('OTP_ENTRY','AUTO','Only backend-validated, correlated OTP references may be entered.'),('LOGIN','REQUIRES_APPROVAL','Login is security-sensitive and requires approval.'),('FILE_UPLOAD','REQUIRES_APPROVAL','File upload requires review of the exact job package.'),('APPLICATION_SUBMISSION','REQUIRES_APPROVAL','Submission requires explicit final approval.')) as x(action_kind, autonomy_level, reason) where not exists (select 1 from autonomy_policies p where p.action_kind=x.action_kind);